$ErrorActionPreference='Stop'
$here=$PSScriptRoot
Import-Module (Join-Path $here 'Repato.AgentOrchestration.psm1') -Force
$module=Import-Module (Join-Path $here 'Repato.MayaQaWorkflow.psm1') -Force -WarningAction SilentlyContinue -PassThru
$root=Join-Path ([IO.Path]::GetTempPath()) ('maya-candidate-retirement-'+[guid]::NewGuid().ToString('N'))
$taskId='task-candidate-retirement';$workflowId='workflow-candidate-retirement';$failedAttempt='failed-attempt';$failedRun='failed-run';$recoveredAttempt='recovered-attempt';$recoveredRun='recovered-run'
try {
    $qa=Join-Path $root 'QA';$runs=Join-Path $qa 'TestRuns';$fixtures=Join-Path $qa 'Fixtures';$runtime=Join-Path $runs ($recoveredRun+'-qa-failure-recovery');$prepRuntime=Join-Path $runs 'fixture-preparation';$null=New-Item -ItemType Directory -Path $runtime,$prepRuntime,$fixtures -Force
    & $module {param($qaRoot) $script:RecoveryTestQaRoot=$qaRoot;Set-Item -Path Function:Get-MayaQaRoot -Value { $script:RecoveryTestQaRoot };Set-Item -Path Function:Get-MayaQaRuntimeRoot -Value { Join-Path $script:RecoveryTestQaRoot 'TestRuns' }} $qa
    $model=Join-Path $runtime 'model.rvt';[IO.File]::WriteAllBytes($model,[byte[]](1,2,3,4));$modelHash=(Get-FileHash $model -Algorithm SHA256).Hash;$source=Join-Path $fixtures 'CreatePlanViewsEmpty.rvt';[IO.File]::WriteAllBytes($source,[byte[]](4,3,2,1));$sourceHash=(Get-FileHash $source -Algorithm SHA256).Hash
    $prepModel=Join-Path $prepRuntime 'model.rvt';Copy-Item $model $prepModel;$prepAttempt='fixture-attempt';$prepRun='fixture-run';$prepRequest=Join-Path $prepRuntime 'fixture.request.json';$prepResult=$prepRequest+'.preparation.json';([ordered]@{operation='prepare-disposable-create-plan-views-fixture';taskId=$taskId;workflowId=$workflowId;attemptId=$prepAttempt;runId=$prepRun;requestPath=$prepRequest;modelPath=$prepModel;modelSha256=$sourceHash;outputPath=$prepResult}|ConvertTo-Json)|Set-Content $prepRequest;([ordered]@{Status='Passed';TaskId=$taskId;WorkflowId=$workflowId;AttemptId=$prepAttempt;RunId=$prepRun;ModelPath=$prepModel;SourceModelSha256=$sourceHash;PreparedModelSha256=$modelHash}|ConvertTo-Json)|Set-Content $prepResult;$prepReqHash=(Get-FileHash $prepRequest -Algorithm SHA256).Hash;$prepResultHash=(Get-FileHash $prepResult -Algorithm SHA256).Hash
    ([ordered]@{fixtureId='CreatePlanViewsEmpty';sourceSha256=$sourceHash;preparedModelSha256=$modelHash;fixturePreparationRequestPath=$prepRequest;fixturePreparationRequestSha256=$prepReqHash;fixturePreparationResultPath=$prepResult;fixturePreparationResultSha256=$prepResultHash;fixturePreparationAttemptId=$prepAttempt;fixturePreparationRunId=$prepRun}|ConvertTo-Json)|Set-Content ($model+'.fixture.json')
    $failedRuntime=Join-Path $runs ($failedRun+'-failed');$null=New-Item -ItemType Directory -Path $failedRuntime -Force;$failedModel=Join-Path $failedRuntime 'model.rvt';[IO.File]::WriteAllBytes($failedModel,[byte[]](9,8,7,6));$failedModelHash=(Get-FileHash $failedModel -Algorithm SHA256).Hash
    $result=Join-Path $root 'failed.result.json';$report=Join-Path $root 'failed.report.json';Set-Content $result '{"Status":"Failed"}';Set-Content $report '{"Status":"Failed"}'
    $resultHash=(Get-FileHash $result -Algorithm SHA256).Hash;$reportHash=(Get-FileHash $report -Algorithm SHA256).Hash
    $store=Join-Path $root 'Store';New-RepatoTask $store $taskId 'Candidate retirement' 'retirement contract' 'qa/native-failure'|Out-Null
    Invoke-RepatoStoreMutation $store {param($d,$preview)
        $t=Find-RepatoTask $d $taskId;$t.revision=8;$t.status='in-progress';$t.workflowStage='approval'
        $t|Add-Member NoteProperty mayaPlan ([pscustomobject]@{WorkflowId=$workflowId;QaWorkflowId='create-plan-views-v1'}) -Force
        $t|Add-Member NoteProperty mayaTaraQaPacket ([pscustomobject]@{TaskId=$taskId;WorkflowId=$workflowId;QaWorkflowId='create-plan-views-v1';RunId=$failedRun;AttemptId=$failedAttempt;ModelPath=$failedModel;SidecarPath=$failedModel+'.fixture.json'}) -Force
        $t|Add-Member NoteProperty mayaTaraAttempt ([pscustomobject]@{TaskId=$taskId;WorkflowId=$workflowId;AttemptId=$recoveredAttempt;RunId=$recoveredRun;RuntimeRoot=$runtime;Stage='prepared'}) -Force
        $t|Add-Member NoteProperty mayaTaraExecution ([pscustomobject]@{TaskId=$taskId;WorkflowId=$workflowId;QaWorkflowId='create-plan-views-v1';AttemptId=$recoveredAttempt;RunId=$recoveredRun;Stage='prepared';ExecutionStatus='Prepared';ClaimStatus='unclaimed';DisposableRuntimeRoot=$runtime;DisposableModelPath=$model;DisposableModelSha256=$modelHash;FixturePreparationEvidence=[pscustomobject]@{ResultSha256=$prepResultHash};AuthoritativeFixturePath=$source;AuthoritativeFixtureSha256=$sourceHash;SideEffectsPerformed=$false;VerificationStatus='Pending';CompletionStatus='Pending'}) -Force
        $t|Add-Member NoteProperty mayaTaraExecutionHistory ([object[]]@([pscustomobject]@{TaskId=$taskId;WorkflowId=$workflowId;QaWorkflowId='create-plan-views-v1';AttemptId=$failedAttempt;RunId=$failedRun;FailureCode='native-qa-failed';ReplacementAttemptId=$recoveredAttempt;ReplacementRunId=$recoveredRun;DisposableModelPath=$failedModel;DisposableModelSha256=$failedModelHash;ResultPath=$result;ResultSha256=$resultHash;ReportPath=$report;ReportSha256=$reportHash})) -Force
        $t|Add-Member NoteProperty approvalRequests ([object[]]@([pscustomobject]@{requestId='legacy-approval-record';action='other';status='rejected'},[pscustomobject]@{requestId='consumed-approval';action='qa-run';attemptId=$failedAttempt;runId=$failedRun;status='approved';consumedUtc='2026-10-14T03:46:46Z'})) -Force
        $t|Add-Member NoteProperty deploymentWorkflows ([object[]]@([pscustomobject]@{taskId=$taskId;workflowId=$workflowId;qaWorkflowId='create-plan-views-v1';workflowRevision=5;qaRunId=$failedRun;qaModelPath=$failedModel;qaHandoffId='handoff';qaHandoff=[pscustomobject]@{HandoffId='handoff'};qaBuildStatus='succeeded';qaBuildRequest=[pscustomobject]@{BuildRequestId='old-build'};qaBuildEvidence=[pscustomobject]@{ArtifactSha256=('B'*64)}})) -Force
        $t
    }|Out-Null
    $badRejected=$false;try{Archive-MayaQaRecoveredAttemptForCandidateReplacement -StoreRoot $store -TaskId $taskId -WorkflowId $workflowId -FailedAttemptId $failedAttempt -RecoveredAttemptId $recoveredAttempt -RecoveredRunId $recoveredRun -ExpectedTaskRevision 7 -ProcessProvider { @() }|Out-Null}catch{$badRejected=$_.Exception.Message -match 'task revision is stale'}
    if(!$badRejected){throw 'Stale retirement revision was not rejected.'}
    $dry=Archive-MayaQaRecoveredAttemptForCandidateReplacement -StoreRoot $store -TaskId $taskId -WorkflowId $workflowId -FailedAttemptId $failedAttempt -RecoveredAttemptId $recoveredAttempt -RecoveredRunId $recoveredRun -ExpectedTaskRevision 8 -ProcessProvider { @() } -DryRun
    if($dry.NativeLaunchPerformed -or !$dry.FailedEvidencePreserved -or !$dry.ConsumedApprovalPreserved){throw 'Dry-run retirement contract failed.'}
    $resultBefore=(Get-FileHash $result -Algorithm SHA256).Hash;$reportBefore=(Get-FileHash $report -Algorithm SHA256).Hash
    $retired=Archive-MayaQaRecoveredAttemptForCandidateReplacement -StoreRoot $store -TaskId $taskId -WorkflowId $workflowId -FailedAttemptId $failedAttempt -RecoveredAttemptId $recoveredAttempt -RecoveredRunId $recoveredRun -ExpectedTaskRevision 8 -ProcessProvider { @() }
    $t=Find-RepatoTask (Read-RepatoTaskStore $store) $taskId;$w=@($t.deploymentWorkflows|Where-Object workflowId -ceq $workflowId)[0]
    if($retired.TaskStage -cne 'build-checks' -or $t.status -cne 'in-progress' -or $t.workflowStage -cne 'build-checks' -or $t.mayaTaraAttempt -or $t.mayaTaraExecution -or $t.mayaTaraQaPacket){throw 'Retirement did not clear active QA pointers or advance to build-checks.'}
    $preservedApproval=@($t.approvalRequests|Where-Object {$_.PSObject.Properties['requestId'] -and $_.requestId -ceq 'consumed-approval'});if($preservedApproval.Count -ne 1 -or $preservedApproval[0].status -cne 'approved' -or !$preservedApproval[0].consumedUtc){throw 'Consumed historical approval was changed.'}
    if(@($t.mayaTaraExecutionHistory|Where-Object {$_.AttemptId -ceq $failedAttempt -and $_.FailureCode -ceq 'native-qa-failed'}).Count -ne 1 -or @($t.mayaTaraExecutionHistory|Where-Object {$_.AttemptId -ceq $recoveredAttempt -and $_.FailureCode -ceq 'candidate-replacement-required'}).Count -ne 1){throw 'Failed and recovered execution history was not retained.'}
    if($w.qaRunId -or $w.qaHandoffId -or $w.qaModelPath -or @($w.qaHandoffHistory|Where-Object RunId -ceq $failedRun).Count -ne 1){throw 'Workflow run/handoff was not archived and cleared.'}
    if((Get-FileHash $result -Algorithm SHA256).Hash -ine $resultBefore -or (Get-FileHash $report -Algorithm SHA256).Hash -ine $reportBefore){throw 'Historical failure receipt/report changed.'}
    $duplicateRejected=$false;try{Archive-MayaQaRecoveredAttemptForCandidateReplacement -StoreRoot $store -TaskId $taskId -WorkflowId $workflowId -FailedAttemptId $failedAttempt -RecoveredAttemptId $recoveredAttempt -RecoveredRunId $recoveredRun -ExpectedTaskRevision ([long]$t.revision) -ProcessProvider { @() }|Out-Null}catch{$duplicateRejected=$_.Exception.Message -match 'recovered in-progress approval state'}
    if(!$duplicateRejected){throw 'Repeated retirement unexpectedly passed the state gate.'}
    [pscustomobject]@{Success=$true;StaleRevisionRejected=$true;DryRunWasReadOnly=$true;TaskReadyForReplacementBuild=$true;FailedEvidencePreserved=$true;ConsumedApprovalPreserved=$true;WorkflowBindingsArchived=$true;NativeLaunchPerformed=$false}|ConvertTo-Json -Compress
} finally {if(Test-Path -LiteralPath $root){Remove-Item -LiteralPath $root -Recurse -Force}}
